const orders = [];
const permute = (done, rest) => {
  if (rest.length === 0) {
    orders.push(done);
    return;
  }
  rest.forEach((n, i) =>
    permute([...done, n], [...rest.slice(0, i), ...rest.slice(i + 1)])
  );
};
permute([], names);
