    Math.abs(at('C') - at('D')) === 3 &&
    at('E') === at('A') + 1 &&
    at('D') < at('B') &&
    Math.abs(at('A') - at('C')) !== 1
  );
};
const found = orders.filter(fits);
return found.length === 1 ? found[0].join('') : 'not unique';
